using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SearingRitualCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/SearingRitualCustomDescription", order = 0)]
public class SearingRitualCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string localizedOnePlusChanting = base.localizationManager.GetLocalizedOnePlusChanting();
		string actionDescription = (battleAction as SearingRitualAction).ChantingAction.GetActionDescription(1);
		return GetFormattedDescription(battleAction, localizedOnePlusChanting) + "\n" + actionDescription;
	}

	protected string GetFormattedDescription(BattleAction battleAction, string secondArgument)
	{
		string firstArgument = (battleAction as SearingRitualAction).ReliefDefaultEffectAction.GetActionDescription(-1).RemoveLast();
		return base.localizationManager.GetLocalizedWhereX(firstArgument, y: false, secondArgument);
	}
}
